lab.solution:
#include <stdio.h>

int main(void) {
    unsigned n = 0;
    n |= 1u << 2;
    n |= 1u << 4;
    printf("after set 2,4: %u\n", n);
    printf("bit 4 set: %s\n", (n & (1u << 4)) ? "yes" : "no");
    unsigned x = n, count = 0;
    while (x) { count += x & 1u; x >>= 1; }
    printf("popcount(20): %u\n", count);
    return 0;
}
